<?php // TRIP SECTION: cost-allocation ledger after settlement. Share = Ci + (Ci/ΣC)×F + Effort fee ?>
<?php if(!in_array($t['status'],['delivered','settled'])||!($owner||$mod||$mem)) return;
$ls=rows("SELECT m.*,u.name FROM trip_members m JOIN users u ON u.id=m.user_id WHERE m.trip_id=? AND m.status='settled' ORDER BY u.name",'i',$id); $sum=fn($k)=>array_sum(array_column($ls,$k)); ?>
<div class="card" data-tour="ledger"><h3>Cost-allocation ledger</h3><p class="muted adv">Shareᵢ = Cᵢ + (Cᵢ / ΣC) × F + Effort Fee(Cᵢ), where F = <?=peso($t['expenses'])?>.</p>
<div class="x"><table><tr><th>Family</th><th class="n">Items Cᵢ</th><th class="n adv">Cᵢ/ΣC</th><th class="n">Expenses</th><th class="n">Effort fee</th><th class="n">Share</th><th class="n">Paid</th><th class="n">Refund/collect</th><th class="n">Saved vs. supermarket</th><th>Pickup</th></tr>
<?php $C=$sum('item_cost'); foreach($ls as $l) echo '<tr><td>'.h($l['name']).'</td><td class="n">'.peso($l['item_cost']).'</td><td class="n adv">'.($C>0?number_format($l['item_cost']/$C,2):'0.00').'</td><td class="n">'.peso($l['expense_share']).'</td><td class="n">'.peso($l['effort_fee']).'</td><td class="n"><b>'.peso($l['share']).'</b></td><td class="n">'.peso($l['paid']).'</td><td class="n">'.($l['balance']>=0?'+':'−').peso(abs($l['balance'])).'</td><td class="n">'.(($s=member_savings($id,$l['user_id']))?peso($s['saved']).' <small>('.$s['pct'].'%)</small>':'-').'</td><td>'.tag($l['pickup']).'</td></tr>'; ?>
<tfoot><tr><td>Total</td><td class="n"><?=peso($C)?></td><td class="n adv">1.00</td><td class="n"><?=peso($sum('expense_share'))?></td><td class="n"><?=peso($sum('effort_fee'))?></td><td class="n"><?=peso($sum('share'))?></td><td class="n"><?=peso($sum('paid'))?></td><td class="n"><?=peso($sum('balance'))?></td><td class="n"><?=peso(array_sum(array_map(fn($l)=>member_savings($id,$l['user_id'])['saved']??0,$ls)))?></td><td></td></tr></tfoot></table></div>
<?php if($owner) echo '<p><small>Your take: '.peso($sum('share')).' total = items reimbursed '.peso($C).' + expenses '.peso($sum('expense_share')).' + effort fees <b>'.peso($sum('effort_fee')).'</b>.</small></p>'; ?></div>
